#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("USAGE\n");
        return 0;
    }
    if (strcmp(argv[1], "escape") == 0) {
        // escape mode
        char *input = argv[2];
        int len = strlen(input);
        char output[len + 1];
        int j = 0;
        for (int i = 0; i < len; i++) {
            if (input[i] == '\\') {
                output[j++] = '\';
                output[j++] = '\';
            } else if (input[i] == '\"') {
                output[j++] = '\';
                output[j++] = '\"';
            } else {
                output[j++] = input[i];
            }
        }
        output[j] = '\0';
        printf("%s\n", output);
    } else if (strcmp(argv[1], "unescape") == 0) {
        // unescape mode
        char *input = argv[2];
        int len = strlen(input);
        char output[len + 1];
        int j = 0;
        for (int i = 0; i < len; i++) {
            if (input[i] == '\') {
                if (i + 1 < len) {
                    if (input[i + 1] == '\') {
                        output[j++] = '\';
                        i++;
                    } else if (input[i + 1] == '\"') {
                        output[j++] = '\"';
                        i++;
                    }
                }
            } else {
                output[j++] = input[i];
            }
        }
        output[j] = '\0';
        printf("%s\n", output);
    } else {
        printf("INVALID_MODE\n");
    }
    return 0;
}
